-- guarded so re-running does not duplicate rows.
BEGIN;

INSERT INTO legal_cases
  (case_name, citation, jurisdiction, court, year, facts, issues, decision, ratio, verification_status)
SELECT
  'Storer v Manchester City Council', '[1974] 1 WLR 1403', 'England and Wales', 'Court of Appeal (Civil Division), England', '1974',
  'In 1970 the defendant council, then Conservative-controlled, adopted a policy of selling council houses to sitting tenants. It instructed the town clerk to devise a simple form of agreement so that sales could take effect as early as possible, deliberately dispensing with the usual conveyancing formalities. The plaintiff, Desmond Harry Storer, was the tenant of 174 Charlestown Road, a council house. By a letter dated 9 March 1971 the town clerk wrote: ''I understand you wish to purchase your Council house and enclose the Agreement for Sale. If you will sign the Agreement and return it to me I will send you the Agreement signed on behalf of the Corporation in exchange.'' The enclosed form had the purchaser, property, price, mortgage amount and monthly repayments filled in; only item 7 (the date the tenancy would cease and mortgage repayments begin) was left blank. The plaintiff signed the agreement and returned it. In May 1971 Labour took control of the council, reversed the policy, and informed him it would not proceed because contracts had not been formally exchanged. He sued for specific performance, alleging a binding contract. The county court judge found for him; the council appealed.', 'Analytical summary, not a verbatim formulation: (1) whether a contract of sale had been concluded by offer and acceptance notwithstanding that the contracts had not been formally exchanged; (2) whether the council''s letter and the enclosed agreement amounted to an offer capable of acceptance; and (3) whether the blank commencement item deprived the agreement of certainty.', 'Appeal dismissed. A binding contract for the sale of the house had been concluded by offer and acceptance when the plaintiff accepted the offer contained in the letter of 9 March by signing the agreement for sale and returning it to the council, notwithstanding that contracts had not been exchanged and the contract had not been signed on behalf of the council. The letter of 9 March was a sufficient note or memorandum. Specific performance was a proper remedy.', 'Where parties have not made their arrangement ''subject to contract'', the only question is whether a contract has been concluded; and whether it has been concluded is judged objectively, from what the parties said and did, not from their uncommunicated intentions. The council''s scheme was expressly designed to dispense with legal formalities, and exchange of contracts was one such formality. The council therefore became contractually bound when the tenant signed and returned the agreement, the blank commencement date being a matter of administrative detail only.', 'verified'
WHERE NOT EXISTS (
  SELECT 1 FROM legal_cases WHERE citation = '[1974] 1 WLR 1403');

INSERT INTO case_mnemonics (case_id, mnemonic)
SELECT id, 'SIMPLE — Scheme (sell council houses) · Instructed town clerk · Missing only the date · Posted back by tenant · Labour cancelled · Exchange held unnecessary. | RULE: NOT ''subject to contract'' → NO formalities needed; OBJECTIVE words and conduct decide. | TRIGGER: Whenever a question asks whether an offer was intended to be binding, or whether a land sale needs formal exchange.'
FROM legal_cases WHERE citation = '[1974] 1 WLR 1403';

INSERT INTO legal_cases
  (case_name, citation, jurisdiction, court, year, facts, issues, decision, ratio, verification_status)
SELECT
  'Alhaji M. C. Dahiru & Anor v Alhaji Bubakare Kamale', '(2005) 9 NWLR (Pt 929) 8', 'Nigeria', 'Supreme Court of Nigeria (on appeal from the Court of Appeal, Jos Division, and the High Court of Adamawa State)', '2005',
  'The litigation arose from the sale of the respondent''s property at Mallamre Ward, Jimeta-Yola, Adamawa State, covered by Statutory Certificate of Occupancy No. GS/6706. The respondent (as plaintiff) pleaded that he had agreed to sell to the 1st appellant for a stated sum, had received a part-payment of N600,000 out of a N650,000 contract price, and that no valid contract had been reached. His writ, taken out on 31 May 1994 in the Adamawa State High Court (suit No. ADSY/39/94, Gwam J), sought declarations that no valid contract existed, that any transfer was void for want of the Governor''s consent under the Land Use Act, that the 1st defendant had no title beyond a refund of the N600,000, delivery up of the title documents, N400,000 for trespass and a perpetual injunction. Each defendant counter-claimed; the 1st defendant sought specific performance, a declaration that he held the certificate of occupancy in equity, a declaration that only N50,000 remained outstanding, an injunction and N1,000,000 general damages, pleading that he had substantially altered his position under the contract. The respondent obtained judgment in the High Court and the appellants, having obtained leave on 16 March 1997, appealed on nine grounds.', 'Analytical summary; the issues were not formulated in the ruling read: (1) whether on the pleadings and evidence a valid contract of sale had been concluded; (2) whether the non-obtaining of the Governor''s consent under the Land Use Act rendered the transaction void; and (3) before the Court of Appeal, whether the appellants could raise for the first time the new point about the effect of the part-payment.', 'The Court of Appeal held that a fresh issue would not be entertained where it was not canvassed below and no special circumstance was shown; the application failed and the ruling was dismissed with N2,000 costs. The Supreme Court allowed the substantive appeal in 2005. MARK: the precise terms of the Supreme Court''s orders were not established from the materials located in this search and must not be stated as if verified.', 'For the proposition the case is actually used for in Nigerian practice: for a contract to exist there must be a definite offer, an unqualified acceptance of that offer and legal consideration; there must be mutuality of purpose and intention, and the two contracting parties must agree. A qualified acceptance is simply a counter-offer and does not give rise to a binding contract. MARK: this ratio is taken from the textbook and from reported Nigerian judgments citing the case, not from the full Supreme Court text, and is therefore PARTLY VERIFIED.', 'partly'
WHERE NOT EXISTS (
  SELECT 1 FROM legal_cases WHERE citation = '(2005) 9 NWLR (Pt 929) 8');

INSERT INTO case_mnemonics (case_id, mnemonic)
SELECT id, 'SALE — Sold at N650,000 · Advance of N600,000 paid · Land Use Act consent missing · Everything counter-claimed. | RULE: O-A-C: Offer + unqualified Acceptance + Consideration = Contract. Vary the acceptance and you have C-O, not A. | TRIGGER: Any time a reply to an offer adds, subtracts or alters a term, or a question asks what must co-exist for a contract to exist.'
FROM legal_cases WHERE citation = '(2005) 9 NWLR (Pt 929) 8';

INSERT INTO legal_cases
  (case_name, citation, jurisdiction, court, year, facts, issues, decision, ratio, verification_status)
SELECT
  'United Bank for Africa Ltd v Tejumola & Sons Ltd', '(1988) 2 NWLR (Pt 79) 662', 'Nigeria', 'Supreme Court of Nigeria (on appeal from the Court of Appeal, Lagos Division, and the Lagos High Court)', '1988',
  'Tejumola & Sons Ltd owned premises at 3 Docemo Street and 42 Idumagbo Avenue, Lagos. After lengthy negotiations, UBA wrote on 19 April 1982 a letter headed ''Subject to Contract'' offering to take a sub-lease: 15 years from the date physical possession was given, with the bank reserving the right to break at the end of the 5th and 10th years, at N215 per square metre per annum revisable every five years, payable five years in advance, and ''subject to your showing evidence of good title''. Tejumola replied the same day accepting the terms, confirmed the covenants, and requested that the bank take physical possession on 1 May 1982 with the five years'' advance. The bank then raised structural doubts (the building was said to have collapsed during construction); the landlord paid for engineers, and Ove Arup & Partners confirmed the building was safe for banking use. At the bank''s request the landlord carried out substantial alterations at its own cost. On 28 October 1982, after its own officers had inspected and been satisfied, the bank wrote calling off the transaction. The landlord sued for N2,000,000 special and general damages.', 'As formulated by the parties and adopted by the Supreme Court: whether, on the pleadings and the evidence, the finding that there was an agreement that the lease should commence on 1 May 1982 can be sustained.', 'The Supreme Court allowed the appeal. There was no concluded contract. The offer had been made ''subject to contract''; the commencement date — an essential term of an agreement for a lease — had never been agreed; the landlord''s letter proposing 1 May 1982 was a counter-offer which could only have been accepted by the bank actually taking physical possession, which never happened. The trial court and the Court of Appeal were both wrong to fix 1 May 1982 as the agreed commencement date. The plaintiff''s claims were dismissed.', 'An agreement for a lease is subject to the general principles of contract: there is no binding contract until the parties are ad idem on the cardinal terms, and for a lease those terms include the parties, the property, the length of the term, the rent and the date of commencement. Where a term is left to be fixed by reference to a contingency that has not occurred, there is no agreement on that term and therefore no enforceable contract. An offer expressed to be ''subject to contract'' keeps the matter in negotiation until a formal contract is drawn up and executed, and either party may walk away in the meantime.', 'verified'
WHERE NOT EXISTS (
  SELECT 1 FROM legal_cases WHERE citation = '(1988) 2 NWLR (Pt 79) 662');

INSERT INTO case_mnemonics (case_id, mnemonic)
SELECT id, 'FIRM-B — Fifteen years · Intending bank · Rent N215 · Marks ''SUBJECT TO CONTRACT'' · Building alterations · Bank walked away. | RULE: P-P-T-R-C: Parties, Property, Term, Rent, Commencement — miss one and there is no lease. | TRIGGER: When you see the words ''subject to contract'', or a lease/land question where one cardinal term is still open.'
FROM legal_cases WHERE citation = '(1988) 2 NWLR (Pt 79) 662';

INSERT INTO legal_cases
  (case_name, citation, jurisdiction, court, year, facts, issues, decision, ratio, verification_status)
SELECT
  'Agomo (also reported as Agoma) v Guinness (Nigeria) Ltd', '(1995) 2 NWLR (Pt 380) 672', 'Nigeria', 'Supreme Court of Nigeria', '1995',
  'The appellant was an employee of Guinness Nigeria Ltd who was laid off when the company reduced production. Her employment was terminated with effect from 14 July 1984, and on 7 July 1984 she collected her terminal benefits, which included two months'' salary in lieu of notice. She later relied on an internal document (Exhibit B), a directive instructing the company''s Personnel Department to recruit at least 1,000 employees, adding that most of those to be recruited would be persons laid off a few months earlier. She argued that Exhibit B was an offer made to the class of retrenched workers, that she belonged to that class, and that she had accepted it by signifying that she was ready, willing and available — thus creating a contract of employment. The company denied that any offer had been made.', 'Analytical summary: (1) whether Exhibit B was an offer to the class of retrenched employees capable of acceptance by the appellant; and (2) whether, having accepted her terminal benefits, the appellant could still assert a subsisting contract of employment.', 'Appeal dismissed. Exhibit B was an internal administrative directive to the Personnel Department and not an offer to the appellant or to any member of her class; it said ''most of those to be recruited'' and not ''all'', so she could not bring herself within it. Even if it had been an offer, it was addressed to employees, and she had ceased to be one on 7 July 1984. Her acceptance of terminal benefits including salary in lieu of notice put an end to any contract, real or imagined.', 'An offer is a proposition put by one person to another coupled with an intimation that the offeror is willing to be bound by that proposition; it must be communicated to the offeree and must evince a present intention to be bound. An internal instruction to a company''s own department, which commits the company to nothing and is addressed to no offeree, is not an offer. An employee who accepts terminal benefits including salary in lieu of notice cannot afterwards assert a subsisting contract.', 'partly'
WHERE NOT EXISTS (
  SELECT 1 FROM legal_cases WHERE citation = '(1995) 2 NWLR (Pt 380) 672');

INSERT INTO case_mnemonics (case_id, mnemonic)
SELECT id, 'LAID — Laid off · Accepted benefits · Internal directive · Declared availability. | RULE: PROPOSITION + INTIMATION + COMMUNICATION = OFFER. A memo to your own staff is none of the three. | TRIGGER: When the alleged offer is an internal memo, circular, advertisement or general announcement and you must ask ''was this addressed to and communicated to the offeree?'''
FROM legal_cases WHERE citation = '(1995) 2 NWLR (Pt 380) 672';

INSERT INTO legal_cases
  (case_name, citation, jurisdiction, court, year, facts, issues, decision, ratio, verification_status)
SELECT
  'Sparkling Breweries Ltd & 5 Ors v Union Bank of Nigeria Ltd', '(2001) 15 NWLR (Pt 737) 539', 'Nigeria', 'Supreme Court of Nigeria', '2001',
  'PARTLY VERIFIED. The appellants were a group of companies (Sparkling Breweries Ltd and five others). They requested a letter of credit from the respondent bank. The bank granted the facility but later cancelled it, which broke down the appellants'' contractual arrangements with third parties. The appellants sued on several grounds, including unlawful interference with their contracts with third parties, and failed at trial and on appeal. MARK: this account rests on law-firm commentary, not on the judgment text; it is set out in the secondary-source block below and must not be treated as the court''s findings.', 'Not established from the materials located, save that the appeal engaged (i) the requisites of the tort of unlawful interference with contractual relations and (ii) the consequences of grounds of appeal on which no issue is predicated.', 'PARTLY VERIFIED. On the authorities citing it: the Supreme Court held that damages for tortious interference cannot be granted where the defendant''s act is not itself unlawful (at 560-561, per Ogbuagu JSC), and that a ground of appeal on which no issue is predicated is deemed abandoned and liable to be struck out (at 556).', 'For contract purposes the case is relied on for a general statement of what an offer is: an expression of readiness to contract on the terms specified by the offeror which, when accepted by the offeree, will give rise to a binding contract, acceptance being what converts the offer into a contract. MARK: the case''s own ratio, on the tort of unlawful interference, is not a contract-law ratio and should not be conflated with it.', 'partly'
WHERE NOT EXISTS (
  SELECT 1 FROM legal_cases WHERE citation = '(2001) 15 NWLR (Pt 737) 539');

INSERT INTO case_mnemonics (case_id, mnemonic)
SELECT id, 'LC — Letter of Credit asked · Cancelled · Loss to third-party deals. | RULE: READINESS + SPECIFIED TERMS + ACCEPTANCE = BINDING CONTRACT. | TRIGGER: When you need an apex-court sentence defining offer and acceptance, or when a question involves interference with another''s contract.'
FROM legal_cases WHERE citation = '(2001) 15 NWLR (Pt 737) 539';

INSERT INTO legal_cases
  (case_name, citation, jurisdiction, court, year, facts, issues, decision, ratio, verification_status)
SELECT
  'S. A. Adebanjo v A. A. Brown', '(1990) 3 NWLR (Pt 141) 661', 'Nigeria', 'Supreme Court of Nigeria (on appeal from the Court of Appeal and the High Court of Lagos State)', '1990',
  'The plaintiff, Alfred Adeyinka Brown, owned Plots 1, 9 and 10 at Tanimeda, Surulere, Lagos, having bought them by an indenture of 16 December 1967 registered as No. 87 at page 87 in Volume 1268. The defendant, Adebanjo, a legal practitioner, owned the adjoining Plot 3 Block IV and began building in 1972. While digging the foundation he discovered that part of his structure fell on the plaintiff''s Plot 10. He reported to his vendors, the administrators of Alhaji N. B. Soule, and they approached the plaintiff. An arrangement was reached: the whole of Plot 10 would be released to the defendant, and the plaintiff would be given Plot 2A Block 2 from the defendant''s vendors in substitution. In furtherance of it the plaintiff removed his shed from Plot 10 to Plot 9 at the defendant''s expense. The plaintiff then extended his own building onto Plot 10, which he had agreed to release. When this was pointed out, the plaintiff agreed to accept cash compensation for the portion retained by the defendant, demarcated the boundary with a tape, and directed the defendant to his family surveyor, Alaka, who prepared Plan AL9/1976 in February 1976 for a fee paid by the defendant. When later asked to name his figure, the plaintiff turned round, denied ever consenting, and sued. He issued his writ in February 1977, about five years after the trespass, claiming N2,000 damages and an injunction; he had since died and his son was substituted.', 'Analytical summary from the judgment''s numbered complaints: (1) whether the Court of Appeal was right to hold that the defendant reneged on an agreement for the exchange of plots; (2) whether it was entitled to interfere with the trial court''s findings of fact; (3) whether the breakdown of negotiations was caused by the plaintiff rather than the defendant; and (4) whether estoppel by representation/election applied.', 'Appeal allowed. The Supreme Court restored the trial court''s findings. The plaintiff''s conduct — accepting the substitution of plots, removing his shed at the defendant''s expense, demarcating the boundary and commissioning a survey to assess compensation — induced the defendant to believe he had waived his complaint and to continue building, so the plaintiff could not resile. There was no concluded contract of sale or exchange on which either party could sue, and no particular sum was ever agreed for the portion retained.', 'Where parties are still negotiating and no agreement has been concluded, neither side may rely on what was done in the course of the negotiations as a contract. But a party whose conduct has led the other to believe that a right has been given up or an arrangement accepted, and who has thereby induced the other to act to his detriment, is estopped from resiling from that position. The court also reaffirmed that an appellate court will not disturb findings of fact supported by the evidence absent perversity, and will not make out a case for a party that the party did not make for himself.', 'partly'
WHERE NOT EXISTS (
  SELECT 1 FROM legal_cases WHERE citation = '(1990) 3 NWLR (Pt 141) 661');

INSERT INTO case_mnemonics (case_id, mnemonic)
SELECT id, 'SHED — Shed moved at defendant''s expense · Half plot kept · Engineer surveyed · Denied consent. | RULE: NO CONTRACT → NO CLAIM ON THE DEAL; but CONDUCT + DETRIMENT → ESTOPPEL. | TRIGGER: When negotiations collapse after one side has spent money, or when a land dispute turns on acquiescence rather than agreement.'
FROM legal_cases WHERE citation = '(1990) 3 NWLR (Pt 141) 661';

INSERT INTO legal_cases
  (case_name, citation, jurisdiction, court, year, facts, issues, decision, ratio, verification_status)
SELECT
  'Union Bank of Nigeria Ltd v Sax (Nigeria) Ltd & 2 Ors', '(1994) 8 NWLR (Pt 361) 150', 'Nigeria', 'Supreme Court of Nigeria', '1994',
  'The respondents (as plaintiffs) had obtained loan and overdraft facilities from the appellant bank, secured by mortgage deeds (Exhibits 25, 26 and 27). They later contended that the bank had agreed to grant them a further or additional facility, and that the bank was not entitled to vary the interest rate without their consent or to exercise its power of sale. The dispute turned on whether a further facility had ever been agreed. Despite protracted correspondence, there was no evidence of the amount of the alleged additional loan, the period of repayment, the rate of interest, or the security to be provided. The bank relied on the written mortgage deeds; the respondents sought to rely on extraneous understandings.', 'Analytical summary: (1) whether there was a concluded agreement for a further or additional loan facility; and (2) whether extrinsic evidence was admissible to add to, vary or contradict the written mortgage deeds.', 'There was no concluded agreement for a further facility. The amount of the loan, the period of repayment, the rate of interest and the security were fundamental terms which had to be provided for, and in the absence of agreement on fundamental terms there can be no valid contract. Extrinsic evidence was inadmissible to add to, vary, subtract from or contradict the terms of the written mortgage deeds, and it was not the business of a court to make a contract for the parties.', 'Where the parties to a transaction have not agreed on its fundamental terms, there is no valid contract; the court will not fill the gap. Where they have reduced their agreement to writing, extrinsic evidence is inadmissible to add to, vary, subtract from or contradict the written instrument, and the written document is the authoritative legal source for resolving disagreements about its terms.', 'partly'
WHERE NOT EXISTS (
  SELECT 1 FROM legal_cases WHERE citation = '(1994) 8 NWLR (Pt 361) 150');

INSERT INTO case_mnemonics (case_id, mnemonic)
SELECT id, 'A-P-R-I-S: Amount · Period of repayment · Rate of interest · Instrument in writing · Security. | RULE: NO FUNDAMENTAL TERMS → NO CONTRACT, and NO WRITING → NO EXTRINSIC VARIATION. | TRIGGER: When an alleged agreement leaves the price, amount, duration or subject matter undecided, or when one side tries to add oral terms to a written contract.'
FROM legal_cases WHERE citation = '(1994) 8 NWLR (Pt 361) 150';

COMMIT;
